create function public.driver_wallet_summary() returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object(
 'cod',coalesce((select jsonb_agg(x) from (select coalesce(nullif(s.currency,''),o.currency) as currency,sum(e.cod_amount) as collected,sum(e.received_amount) as deposited,sum(e.outstanding_amount) as outstanding from public.driver_cod_entries e join public.shipments s on s.id=e.shipment_id join public.organization_settings o on o.organization_id=e.organization_id where e.driver_id=(select auth.uid()) and (select private.is_active_mobile_driver()) group by coalesce(nullif(s.currency,''),o.currency))x),'[]'::jsonb),
 'earnings',coalesce((select jsonb_agg(x) from (select currency,sum(case when kind in ('delivery','fixed','bonus') then amount else 0 end) as earned,sum(case when kind='deduction' then amount else 0 end) as deductions,sum(case when kind='payment' then amount else 0 end) as paid,sum(case when kind in ('deduction','payment') then -amount else amount end) as balance from public.driver_earnings where driver_id=(select auth.uid()) and (select private.is_active_mobile_driver()) group by currency)x),'[]'::jsonb));
$$; revoke all on function public.driver_wallet_summary() from public,anon; grant execute on function public.driver_wallet_summary() to authenticated;
